#!/usr/bin/env python3
# remap.py <old-commit> <new-commit> <old-errors.tsv> <new-errors.tsv>: map each new site's line back to the
# old commit through git diff -U0 for the files the diff touches, then print the sites that differ
# (kind, location, message with line numbers inside the message also remapped) as GONE / NEW.
import re, subprocess, sys, collections
old, new, a, b = sys.argv[1:5]
ROOT = '/home/user/fortress-numlib'
names = {'FortressLibrary.fss':'Library/FortressLibrary.fss','FortressLibrary.fsi':'Library/FortressLibrary.fsi',
         'FortressBuiltin.fss':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fss','FortressBuiltin.fsi':'ProjectFortress/LibraryBuiltin/FortressBuiltin.fsi'}
maps = {}
for short, path in names.items():
    d = subprocess.run(['git','-C',ROOT,'diff','-U0',old,new,'--',path],capture_output=True,text=True).stdout
    hunks = []
    for m in re.finditer(r'^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@', d, re.M):
        os_, oc, ns, nc = int(m.group(1)), int(m.group(2) or 1), int(m.group(3)), int(m.group(4) or 1)
        hunks.append((os_, oc, ns, nc))
    maps[short] = hunks
def back(short, n):
    hs = maps.get(short)
    if not hs: return str(n)
    delta = 0
    for os_, oc, ns, nc in hs:
        if nc and ns <= n < ns + nc:
            return 'INS%d' % n if oc == 0 else 'REW%d' % (os_ + min(n - ns, oc - 1))
        if n >= ns + nc: delta = (os_ + oc) - (ns + nc)
        else: break
    return str(n + delta)
pat = re.compile(r'(FortressLibrary\.fs[si]|FortressBuiltin\.fs[si]):(\d+)')
def norm(line, remap):
    if remap: line = pat.sub(lambda m: m.group(1)+':'+back(m.group(1), int(m.group(2))), line)
    return line
def load(f, remap):
    c = collections.Counter()
    for l in open(f):
        if l.startswith('#'): continue
        p = l.rstrip('\n').split('\t')
        c[norm('\t'.join([p[0], p[5], p[6]]), remap)] += 1
    return c
A = load(a, False); B = load(b, True)
for k in sorted(set(A) | set(B)):
    if A[k] != B[k]:
        print(('GONE' if A[k] > B[k] else 'NEW') + '\t%d->%d\t%s' % (A[k], B[k], k[:400]))
EOF
echo ok

